SET search_path=wiareport,public;
CREATE SCHEMA IF NOT EXISTS "wiareport";
CREATE TABLE "epics" ("epic_id" TEXT,"milestone_id" TEXT NOT NULL,"title" TEXT NOT NULL,"owner" TEXT NOT NULL DEFAULT '',"status" TEXT NOT NULL DEFAULT 'planned',"color" TEXT NOT NULL DEFAULT '#0ea5b7',"start_date" TEXT NOT NULL,"end_date" TEXT NOT NULL,"created_at" TEXT NOT NULL,"sort_order" INTEGER NOT NULL DEFAULT 0,PRIMARY KEY("epic_id"));
CREATE TABLE "milestones" ("milestone_id" TEXT,"project_id" TEXT NOT NULL,"title" TEXT NOT NULL,"start_date" TEXT NOT NULL,"end_date" TEXT NOT NULL,"created_at" TEXT NOT NULL,PRIMARY KEY("milestone_id"));
CREATE TABLE "parts" ("part_id" TEXT,"team_id" TEXT NOT NULL,"name" TEXT NOT NULL,"created_at" TEXT NOT NULL,"report_schedule_enabled" INTEGER NOT NULL DEFAULT 0,"report_schedule_weekday" INTEGER NOT NULL DEFAULT 4,"report_schedule_time" TEXT NOT NULL DEFAULT '17:00',"report_schedule_interval_days" INTEGER NOT NULL DEFAULT 7,PRIMARY KEY("part_id"));
CREATE UNIQUE INDEX ON "parts" ("team_id","name");
CREATE TABLE "project" ("project_id" TEXT,"team_id" TEXT NOT NULL,"project_name" TEXT NOT NULL,"created_at" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'in_progress',"completed_at" TEXT,"part_id" TEXT,"sort_order" INTEGER NOT NULL DEFAULT 0,PRIMARY KEY("project_id"));
CREATE INDEX ON "project" ("team_id","part_id");
CREATE TABLE "project_entry" ("entry_id" TEXT NOT NULL,"project_id" TEXT NOT NULL,"is_excluded" INTEGER NOT NULL DEFAULT 0,"progress_log" TEXT NOT NULL DEFAULT '',"risk_issue" TEXT NOT NULL DEFAULT '',"next_plan" TEXT NOT NULL DEFAULT '',"updated_at" TEXT NOT NULL DEFAULT '',"sort_order" INTEGER NOT NULL DEFAULT 0,PRIMARY KEY("entry_id","project_id"));
CREATE TABLE "project_issue" ("issue_id" TEXT,"project_id" TEXT NOT NULL,"entry_id" TEXT NOT NULL,"issue_index" INTEGER NOT NULL,"status" TEXT NOT NULL DEFAULT 'open',"issue" TEXT NOT NULL DEFAULT '',"importance" TEXT NOT NULL DEFAULT '중',"detail" TEXT NOT NULL DEFAULT '',"images" TEXT NOT NULL DEFAULT '[]',"confluence_url" TEXT NOT NULL DEFAULT '',"created_at" TEXT NOT NULL,"updated_at" TEXT NOT NULL DEFAULT '',"resolved_at" TEXT NOT NULL DEFAULT '',"resolution_progress_ids" TEXT NOT NULL DEFAULT '[]',"resolution_comment" TEXT NOT NULL DEFAULT '',PRIMARY KEY("issue_id"),CHECK(status IN ('open', 'resolved')));
CREATE UNIQUE INDEX ON "project_issue" ("entry_id","project_id","issue_index");
CREATE TABLE "project_members" ("project_id" TEXT NOT NULL,"user_id" TEXT NOT NULL,"role" TEXT NOT NULL,PRIMARY KEY("project_id","user_id"),CHECK(role IN ('L', 'M')));
CREATE TABLE "project_plan" ("plan_id" TEXT,"project_id" TEXT NOT NULL,"entry_id" TEXT NOT NULL,"plan_index" INTEGER NOT NULL,"plan" TEXT NOT NULL DEFAULT '',"due" TEXT NOT NULL DEFAULT '',"created_at" TEXT NOT NULL,"updated_at" TEXT NOT NULL DEFAULT '',PRIMARY KEY("plan_id"));
CREATE UNIQUE INDEX ON "project_plan" ("entry_id","project_id","plan_index");
CREATE TABLE "project_progress" ("progress_id" TEXT,"project_id" TEXT NOT NULL,"entry_id" TEXT NOT NULL,"progress_index" INTEGER NOT NULL,"log" TEXT NOT NULL DEFAULT '',"status" TEXT NOT NULL DEFAULT 'done',"date" TEXT NOT NULL DEFAULT '',"detail" TEXT NOT NULL DEFAULT '',"images" TEXT NOT NULL DEFAULT '[]',"confluence_url" TEXT NOT NULL DEFAULT '',"created_at" TEXT NOT NULL,"updated_at" TEXT NOT NULL DEFAULT '',"is_history_hidden" INTEGER NOT NULL DEFAULT 0,PRIMARY KEY("progress_id"),CHECK(status IN ('done', 'in_progress')));
CREATE UNIQUE INDEX ON "project_progress" ("entry_id","project_id","progress_index");
CREATE TABLE "report_entries" ("entry_id" TEXT,"report_id" TEXT NOT NULL,"user_id" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'pending',"created_at" TEXT NOT NULL,"updated_at" TEXT NOT NULL DEFAULT '',PRIMARY KEY("entry_id"));
CREATE UNIQUE INDEX ON "report_entries" ("report_id","user_id");
CREATE TABLE "report_schedule_runs" ("team_id" TEXT NOT NULL,"part_key" TEXT NOT NULL DEFAULT '',"start_date" TEXT NOT NULL,"end_date" TEXT NOT NULL,"report_id" TEXT NOT NULL,"recorded_at" TEXT NOT NULL,PRIMARY KEY("team_id","part_key","start_date"));
CREATE TABLE "reports" ("report_id" TEXT,"team_id" TEXT NOT NULL,"start_date" TEXT NOT NULL,"end_date" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'in_progress',"created_at" TEXT NOT NULL,"completed_at" TEXT,"part_id" TEXT,PRIMARY KEY("report_id"));
CREATE INDEX ON "reports" ("team_id","part_id");
CREATE TABLE "team_event_members" ("event_id" TEXT NOT NULL,"user_id" TEXT NOT NULL,PRIMARY KEY("event_id","user_id"));
CREATE TABLE "team_events" ("event_id" TEXT,"team_id" TEXT NOT NULL,"title" TEXT NOT NULL,"event_type" TEXT NOT NULL DEFAULT 'team',"start_date" TEXT NOT NULL,"end_date" TEXT NOT NULL,"created_at" TEXT NOT NULL,"part_id" TEXT,PRIMARY KEY("event_id"));
CREATE INDEX ON "team_events" ("team_id","part_id");
CREATE TABLE "teams" ("team_id" TEXT,"department" TEXT NOT NULL,"created_at" TEXT NOT NULL,"report_schedule_enabled" INTEGER NOT NULL DEFAULT 1,"report_schedule_weekday" INTEGER NOT NULL DEFAULT 4,"report_schedule_time" TEXT NOT NULL DEFAULT '17:00',"report_schedule_interval_days" INTEGER NOT NULL DEFAULT 7,"parts_enabled" INTEGER NOT NULL DEFAULT 0,PRIMARY KEY("team_id"),platform_team_id TEXT UNIQUE REFERENCES platform.teams(team_id));
CREATE TABLE "members" ("user_id" TEXT,"team_id" TEXT NOT NULL,"name" TEXT NOT NULL,"role" TEXT NOT NULL,"created_at" TEXT NOT NULL,"sort_order" INTEGER NOT NULL DEFAULT 0,"part_id" TEXT,PRIMARY KEY("user_id"),platform_user_id TEXT REFERENCES platform.users(user_id),is_active INTEGER NOT NULL DEFAULT 0,UNIQUE(team_id,platform_user_id));
CREATE INDEX ON "members" ("team_id","part_id");
ALTER TABLE "epics" ADD FOREIGN KEY ("milestone_id") REFERENCES "milestones" ("milestone_id") ON DELETE CASCADE;
ALTER TABLE "milestones" ADD FOREIGN KEY ("project_id") REFERENCES "project" ("project_id") ON DELETE CASCADE;
ALTER TABLE "parts" ADD FOREIGN KEY ("team_id") REFERENCES "teams" ("team_id") ON DELETE CASCADE;
ALTER TABLE "project" ADD FOREIGN KEY ("team_id") REFERENCES "teams" ("team_id") ON DELETE CASCADE;
ALTER TABLE "project" ADD FOREIGN KEY ("part_id") REFERENCES "parts" ("part_id") ON DELETE NO ACTION;
ALTER TABLE "project_entry" ADD FOREIGN KEY ("project_id") REFERENCES "project" ("project_id") ON DELETE CASCADE;
ALTER TABLE "project_entry" ADD FOREIGN KEY ("entry_id") REFERENCES "report_entries" ("entry_id") ON DELETE CASCADE;
ALTER TABLE "project_issue" ADD FOREIGN KEY ("project_id") REFERENCES "project" ("project_id") ON DELETE CASCADE;
ALTER TABLE "project_issue" ADD FOREIGN KEY ("entry_id") REFERENCES "report_entries" ("entry_id") ON DELETE CASCADE;
ALTER TABLE "project_members" ADD FOREIGN KEY ("user_id") REFERENCES "members" ("user_id") ON DELETE CASCADE;
ALTER TABLE "project_members" ADD FOREIGN KEY ("project_id") REFERENCES "project" ("project_id") ON DELETE CASCADE;
ALTER TABLE "project_plan" ADD FOREIGN KEY ("project_id") REFERENCES "project" ("project_id") ON DELETE CASCADE;
ALTER TABLE "project_plan" ADD FOREIGN KEY ("entry_id") REFERENCES "report_entries" ("entry_id") ON DELETE CASCADE;
ALTER TABLE "project_progress" ADD FOREIGN KEY ("project_id") REFERENCES "project" ("project_id") ON DELETE CASCADE;
ALTER TABLE "project_progress" ADD FOREIGN KEY ("entry_id") REFERENCES "report_entries" ("entry_id") ON DELETE CASCADE;
ALTER TABLE "report_entries" ADD FOREIGN KEY ("user_id") REFERENCES "members" ("user_id") ON DELETE CASCADE;
ALTER TABLE "report_entries" ADD FOREIGN KEY ("report_id") REFERENCES "reports" ("report_id") ON DELETE CASCADE;
ALTER TABLE "report_schedule_runs" ADD FOREIGN KEY ("team_id") REFERENCES "teams" ("team_id") ON DELETE CASCADE;
ALTER TABLE "reports" ADD FOREIGN KEY ("team_id") REFERENCES "teams" ("team_id") ON DELETE CASCADE;
ALTER TABLE "reports" ADD FOREIGN KEY ("part_id") REFERENCES "parts" ("part_id") ON DELETE NO ACTION;
ALTER TABLE "team_event_members" ADD FOREIGN KEY ("user_id") REFERENCES "members" ("user_id") ON DELETE CASCADE;
ALTER TABLE "team_event_members" ADD FOREIGN KEY ("event_id") REFERENCES "team_events" ("event_id") ON DELETE CASCADE;
ALTER TABLE "team_events" ADD FOREIGN KEY ("team_id") REFERENCES "teams" ("team_id") ON DELETE CASCADE;
ALTER TABLE "team_events" ADD FOREIGN KEY ("part_id") REFERENCES "parts" ("part_id") ON DELETE NO ACTION;
ALTER TABLE "members" ADD FOREIGN KEY ("team_id") REFERENCES "teams" ("team_id") ON DELETE CASCADE;
ALTER TABLE "members" ADD FOREIGN KEY ("part_id") REFERENCES "parts" ("part_id") ON DELETE NO ACTION;
CREATE TABLE user_activity(platform_user_id TEXT PRIMARY KEY REFERENCES platform.users(user_id),team_id TEXT REFERENCES teams(team_id),last_seen_at TIMESTAMPTZ NOT NULL);
CREATE FUNCTION part_visible(team TEXT,part TEXT) RETURNS BOOLEAN LANGUAGE SQL STABLE AS $$
          SELECT (COALESCE(current_setting('wiareport.team',true),'')='' OR team=current_setting('wiareport.team',true))
           AND (COALESCE(current_setting('wiareport.parts_enabled',true),'0')!='1'
                OR part IS NOT DISTINCT FROM NULLIF(current_setting('wiareport.part',true),'')) $$;
CREATE FUNCTION safe_timestamp(value TEXT) RETURNS TIMESTAMPTZ LANGUAGE plpgsql IMMUTABLE AS $$
          BEGIN RETURN NULLIF(value,'')::timestamptz; EXCEPTION WHEN others THEN RETURN NULL; END $$;
CREATE INDEX ON members(team_id,part_id);
CREATE INDEX ON project(team_id,part_id);
CREATE INDEX ON reports(team_id,part_id);
CREATE INDEX ON team_events(team_id,part_id);
